export const escapeShowcase=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function showcaseMarkup(items,{compact=false,imagesOnly=false,title='社群作品'}={}){
 const e=escapeShowcase;
 if(imagesOnly)return `<section class="showcase compact images-only" aria-label="群聊作品图片轮播">${items.length?items.map((x,index)=>`<article class="showcase-slide" ${index?'hidden':''}><button class="showcase-art" data-co="showcase-open" aria-label="全屏展示群聊作品"><span class="co-poster" data-community-poster="${e(x.postId)}" data-g="${e(x.groupId)}"></span></button></article>`).join(''):'<div class="showcase-art showcase-blank" aria-label="暂无群聊作品"></div>'}</section>`;
 return `<section class="showcase ${compact?'compact':''}" aria-label="社群作品轮播"><header><span>${e(title)}</span><small>每一份美好，都值得被看见</small></header>${items.length?items.map((x,index)=>`<article class="showcase-slide" ${index?'hidden':''}><div class="showcase-art">${x.image?`<img src="${e(x.image)}" alt="${e(x.title)}">`:`<span class="co-poster" data-community-poster="${e(x.postId)}" data-g="${e(x.groupId)}"></span>`}<div class="showcase-danmaku" aria-label="点赞评论弹幕">${[...x.likes.map(user=>`♡ ${e(user)} 觉得很赞`),...x.comments.map(c=>`${e(c.author)}${c.reply?` 回复 ${e(c.reply)}`:''}：${e(c.body)}`)].map(r=>`<template>${r}</template>`).join('')}</div></div><div class="showcase-story"><small>${e(x.group)} · ${e(x.author)}</small><h2>${e(x.caption||x.title)}</h2></div></article>`).join(''):'<div class="showcase-empty">发布第一张海报，让美好在这里流动</div>'}<nav><button data-slide="prev" aria-label="上一张">‹</button><span class="showcase-count">${items.length?'1':'0'} / ${items.length}</span><button data-slide="next" aria-label="下一张">›</button><button data-slide="pause">暂停</button></nav></section>`;
}
export function mountShowcase(root){
 let index=0,elapsed=0,paused=false,emitted=0;const slides=[...root.querySelectorAll('.showcase-slide')];
 const emit=()=>{const layer=slides[index]?.querySelector('.showcase-danmaku');if(!layer)return;const messages=[...layer.querySelectorAll('template')];if(!messages.length)return;const text=messages[emitted%messages.length].content.textContent;const bubble=document.createElement('span');bubble.className='danmaku-message';bubble.textContent=text;bubble.style.top=(12+(emitted%3)*23)+'%';bubble.style.setProperty('--danmaku-width',layer.clientWidth+'px');layer.appendChild(bubble);bubble.addEventListener('animationend',()=>bubble.remove());emitted++;};
 const show=n=>{if(!slides.length)return;slides[index].hidden=true;slides[index].querySelectorAll('.danmaku-message').forEach(x=>x.remove());index=(n+slides.length)%slides.length;slides[index].hidden=false;if(root.querySelector('.showcase-count'))root.querySelector('.showcase-count').textContent=`${index+1} / ${slides.length}`;elapsed=0;emitted=0;emit();};
 root.querySelectorAll('[data-slide]').forEach(b=>b.onclick=()=>{if(b.dataset.slide==='pause'){paused=!paused;root.classList.toggle('is-paused',paused);b.textContent=paused?'播放':'暂停';}else show(index+(b.dataset.slide==='next'?1:-1));});
 const visibility=()=>root.classList.toggle('is-hidden',document.hidden);document.addEventListener('visibilitychange',visibility);visibility();emit();
 const timer=setInterval(()=>{if(!root.isConnected){clearInterval(timer);document.removeEventListener('visibilitychange',visibility);return;}if(paused||document.hidden||!slides.length)return;elapsed+=1800;const count=slides[index].querySelectorAll('template').length;if(elapsed>=(root.classList.contains('images-only')?5400:Math.max(12600,count*1800+8100)))show(index+1);else emit();},1800);
 return ()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visibility);};
}
export const showcaseStyle=`
.showcase{background:#f2f3e9;color:#334334;padding:20px;overflow:hidden}.showcase header{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:16px}.showcase header>span{font-weight:600}.showcase header small{font-size:11px;color:#75836a}.showcase-slide{display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:center;min-height:65vh}.showcase-slide[hidden],.showcase-reactions p[hidden]{display:none!important}.showcase-art{position:relative;overflow:hidden;height:65vh;display:flex;justify-content:center;align-items:center;min-width:0}.showcase-art img,.showcase-art canvas{max-height:100%;max-width:100%;object-fit:contain;box-shadow:0 6px 20px #29392318}.showcase-art .co-poster{height:100%;width:100%;display:flex;justify-content:center;align-items:center;background:transparent}.showcase-story{min-width:0}.showcase-story>small{color:#74846b}.showcase-story h2{font-size:clamp(22px,3vw,42px);line-height:1.6;overflow-wrap:anywhere}.showcase-reactions{color:#617b56;font-size:clamp(15px,1.8vw,24px);line-height:1.8;min-height:100px;overflow-wrap:anywhere}.showcase-reactions p{margin:0}.showcase nav{display:flex;align-items:center;justify-content:center;gap:20px;margin-top:16px}.showcase button{border:0;background:transparent;color:inherit;min-height:36px;min-width:36px;cursor:pointer;font:inherit}.showcase-count{font-size:12px;color:#75836a}.showcase-empty{padding:40px 10px;text-align:center;color:#75836a}.showcase.compact{padding:14px 18px}.compact header{margin-bottom:12px}.compact header small{display:none}.compact .showcase-slide{min-height:180px;grid-template-columns:110px 1fr;gap:16px}.compact .showcase-art{height:180px}.compact .showcase-story h2{font-size:16px;line-height:1.7;margin:12px 0}.compact .showcase-story>small{font-size:10px}.compact .showcase-reactions{font-size:11px;min-height:54px}.compact .showcase-reactions p{display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.compact nav{margin-top:5px;gap:14px}.showcase-entry{display:flex;justify-content:space-between;align-items:center;padding:8px 18px;color:#71845e;font-size:11px}.showcase-entry button{font-size:12px;color:inherit;min-height:36px;background:transparent;border:0;cursor:pointer}@media(max-width:650px){.showcase:not(.compact) .showcase-slide{grid-template-columns:1fr;gap:16px}.showcase:not(.compact) .showcase-art{height:50vh}.showcase:not(.compact) .showcase-story h2{font-size:22px;margin:8px 0}.showcase:not(.compact) .showcase-reactions{min-height:70px}}
.showcase-danmaku{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:2}.danmaku-message{position:absolute;left:100%;white-space:nowrap;color:white;font-weight:600;font-size:clamp(16px,1.6vw,24px);line-height:1.6;padding:5px 14px;border-radius:30px;background:#29402c9c;text-shadow:0 1px 3px #0007;animation:danmaku-fly 8s linear both;will-change:transform}.is-paused .danmaku-message,.is-hidden .danmaku-message{animation-play-state:paused}.compact .showcase-slide{display:block}.compact .showcase-art{height:240px;background:#e7eadc}.compact .showcase-story{padding-top:10px}.compact .showcase-story h2{font-size:13px;margin:5px 0}.compact .danmaku-message{font-size:12px;padding:3px 10px}@keyframes danmaku-fly{from{transform:translateX(0)}to{transform:translateX(calc(-100% - var(--danmaku-width)))}}@media(prefers-reduced-motion:reduce){.danmaku-message{animation:none;position:relative;left:auto;top:auto!important;display:table;margin:8px;white-space:normal;max-width:85%}.showcase-danmaku{display:flex;flex-direction:column;justify-content:flex-start}.danmaku-message:nth-last-child(n+4){display:none}}

.showcase.images-only{padding:0;background:#f0f1e9}.images-only .showcase-slide{min-height:0}.images-only .showcase-art{height:auto;aspect-ratio:16/9;width:100%;padding:0;border:0;border-radius:0;background:#e8ebdf;cursor:pointer}.images-only .showcase-art canvas{box-shadow:none}.images-only .showcase-art>.showcase-backdrop{position:absolute;inset:-8%;width:116%;height:116%;max-width:none;max-height:none;object-fit:cover;filter:blur(18px) brightness(.65);pointer-events:none}.images-only .showcase-art>.co-poster{position:absolute;inset:0;z-index:1;max-height:none}.images-only .showcase-art .co-poster canvas{width:100%;height:100%;max-height:none;object-fit:contain}.images-only .showcase-blank{background:#e8ebdf}.co-chat-switch{display:flex;align-items:center;justify-content:space-between;padding:10px 18px;border-bottom:1px solid #eee;gap:12px}.co-chat-switch strong{font-size:14px;color:#37433b}.co-chat-switch button{display:flex;align-items:center;gap:4px;color:#748a61;font-size:12px;min-height:36px;border:0;background:transparent}.co-chat-options{display:grid;gap:8px}.co-chat-options button{display:flex;justify-content:space-between;align-items:center;text-align:left;background:#f6f7f2;border:0;border-radius:8px;min-height:50px;padding:12px 16px;color:#4c5947}.co-chat-options button.selected{background:#edf3e6;color:#6e8955;font-weight:600}
`;
export function showcaseDocument(items,title){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${escapeShowcase(title)} · 夸夸</title><style>body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;background:#f2f3e9}.display-tools{display:flex;justify-content:space-between;padding:10px 24px;color:#74846b;font-size:12px}.display-tools button{border:0;background:transparent;color:inherit;cursor:pointer;padding:10px}${showcaseStyle}
html,body{width:100%;height:100%;overflow:hidden;background:#10130f}body>.showcase{position:fixed;inset:0;max-width:none;margin:0;padding:0;background:#10130f}body>.showcase>header,body>.showcase .showcase-story,.display-tools>span{display:none}body>.showcase .showcase-slide{display:block;width:100%;height:100%;min-height:0}body>.showcase .showcase-art{width:100%;height:100dvh;background:#10130f}body>.showcase .showcase-art img{width:100%;height:100%;object-fit:contain;box-shadow:none}body>.showcase nav{position:absolute;bottom:max(16px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);z-index:5;color:white;background:#17201999;border-radius:30px;padding:2px 12px;opacity:0;transition:opacity .25s}body>.showcase:hover nav,body>.showcase:focus-within nav,body.controls-visible>.showcase nav{opacity:1}.display-tools{position:fixed;top:max(12px,env(safe-area-inset-top));right:12px;z-index:6;padding:0;color:white;background:#17201999;border-radius:24px;opacity:0;transition:opacity .25s}body:hover .display-tools,body.controls-visible .display-tools,.display-tools:focus-within{opacity:1}body>.showcase .showcase-count{color:#fff}body>.showcase .showcase-danmaku{inset:0 0 15%}</style><div class="display-tools"><span>夸夸 · ${escapeShowcase(title)} · 分享时的作品快照</span><button onclick="document.documentElement.requestFullscreen?.()">全屏展示</button></div>${showcaseMarkup(items,{title})}<script>(${mountShowcase.toString()})(document.querySelector('.showcase'));let hideControls;function revealControls(){document.body.classList.add('controls-visible');clearTimeout(hideControls);hideControls=setTimeout(()=>document.body.classList.remove('controls-visible'),2500);}document.addEventListener('pointerdown',revealControls);document.addEventListener('keydown',revealControls);revealControls();</script></html>`;}
